import{_ as t,o as r,c as a,a0 as n}from"./chunks/framework.BxrwG5q5.js";const f=JSON.parse('{"title":"Concepts & Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md"}'),o={name:"guide/concepts.md"};function s(i,e,g,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="concepts-glossary" tabindex="-1">Concepts &amp; Glossary <a class="header-anchor" href="#concepts-glossary" aria-label="Permalink to &quot;Concepts &amp; Glossary&quot;">​</a></h1><blockquote><p>See also: <a href="/config/guide/getting-started.html">Quick Start</a> · <a href="/config/contributing/architecture.html">Architecture</a> · <a href="/config/api/">SDK Reference</a></p></blockquote><p>A quick reference of key terminology used throughout the documentation, mapped to standard software industry terms where applicable.</p><hr><p><strong>Config / Feature Flag</strong> — A key-value pair that controls application behavior at runtime without a code deploy. Configs can be boolean flags, numbers, strings, JSON, or arrays. <a href="/config/guide/getting-started.html">Learn more →</a></p><p><strong>Context</strong> — The set of user attributes sent to the API for evaluation (e.g., <code>userId</code>, <code>plan</code>, <code>country</code>). Context drives targeting rules and segment membership. <a href="/config/guide/scopes.html">Learn more →</a></p><p><strong>Segments / Audience Segments</strong> — Reusable named cohorts defined by conditions on context attributes. Define once, reference across many flags. Standard term: <em>audience segment</em>. <a href="/config/features/segments.html">Learn more →</a></p><p><strong>Targeting Rules / User Segmentation</strong> — Rules that match context attributes or segment membership to return specific config values. Evaluated in priority order. Powers <strong>A/B testing</strong>, <strong>multivariate testing (MVT)</strong>, and <strong>feature gating</strong>. <a href="/config/features/targeting.html">Learn more →</a></p><p><strong>A/B Testing</strong> — A targeting setup with two variants: a control (default value) and a treatment (targeting rule value). Each user is consistently in one group via sticky bucketing. Multiple variants = <strong>multivariate test (MVT)</strong>. <a href="/config/features/targeting.html">Learn more →</a></p><p><strong>Rollouts / Progressive Delivery</strong> — Percentage-based gradual feature release using <strong>sticky bucketing</strong> (<code>MurmurHash3(flagKey:userId) % 100</code>). The industry pattern is called a <strong>canary release</strong> — start at 5%, validate, ramp up. <a href="/config/features/rollouts.html">Learn more →</a></p><p><strong>Canary Release</strong> — Rolling out a feature to a small percentage of users first, validating impact, then gradually increasing. Implemented via percentage rollouts. <a href="/config/features/rollouts.html">Learn more →</a></p><p><strong>Sticky Bucketing</strong> — Deterministic user-to-bucket assignment ensuring the same user always gets the same variant. Required for valid A/B testing and canary analysis. <a href="/config/features/rollouts.html">Learn more →</a></p><p><strong>Kill Switch</strong> — Setting a flag&#39;s rollout to 0% or its default to <code>false</code> — instantly reverts all users to the safe state with no code deploy. <a href="/config/features/rollouts.html">Learn more →</a></p><p><strong>Ring Deployment</strong> — Releasing through concentric rings of users by risk tolerance (internal → beta cohort → general). Implemented by combining targeting rules (ring 0/1) with rollout percentage (ring 2/3). <a href="/config/features/rollouts.html">Learn more →</a></p><p><strong>Feature Gating</strong> — Restricting a feature to users who meet a condition (plan, role, entitlement). Implemented via targeting rules. <strong>Dependency-based feature gating</strong> — gating one flag on the state of another — is implemented via prerequisites. <a href="/config/features/targeting.html">Learn more →</a></p><p><strong>Dark Launch</strong> — Deploying code behind a <code>false</code> flag (invisible to users) and scheduling or manually activating it later. Decouples code deploy from feature release. <a href="/config/features/scheduling.html">Learn more →</a></p><p><strong>Timed Release</strong> — Scheduling a flag to activate at a specific date/time without manual intervention. <a href="/config/features/scheduling.html">Learn more →</a></p><p><strong>Prerequisites / Dependency Flags / Guard Flags</strong> — A flag that gates another flag. Feature B is only active if guard flag A meets a condition. Prevents inconsistent feature states. <a href="/config/features/prerequisites.html">Learn more →</a></p><p><strong>Environments</strong> — Isolated deployment stages (development, staging, production) with independent configs, API keys, and targeting rules. <a href="/config/features/environments.html">Learn more →</a></p><p><strong>API Keys</strong> — Client keys (<code>cid_</code>) trigger server-side evaluation (rules never exposed to browser). Server keys (<code>svr_</code>) return full flag data for client-side evaluation. <a href="/config/api/">Learn more →</a></p><p><strong>Evaluation Pipeline</strong> — The order in which flags are resolved: archived → prerequisites → overrides → schedule → targeting → rollout → default. <a href="/config/contributing/architecture.html">Learn more →</a></p><p><strong>Loading Strategies</strong> — How the SDK fetches on init: <strong>optimistic</strong> (instant defaults, background fetch), <strong>pessimistic</strong> (blocks until data arrives), <strong>deferred</strong> (manual trigger). <a href="/config/guide/loading-strategies.html">Learn more →</a></p><p><strong>Circuit Breaker</strong> — The SDK stops retrying for 5 minutes after 401/403 errors, preventing wasted requests on misconfigured clients. <a href="/config/api/">Learn more →</a></p><p><strong>RBAC</strong> — Role-based access control: Viewer (read-only), Editor (read/write configs), Admin (full access including team and API keys). <a href="/config/features/team.html">Learn more →</a></p>',24)])])}const p=t(o,[["render",s]]);export{f as __pageData,p as default};
